from dataclasses import dataclass
from fastapi import APIRouter, Depends, Header, HTTPException
from app.auth import decode_access_token
from app.broker import broker

router = APIRouter()

@dataclass
class RequestContext:
    subject: str
    tenant_id: str
    role: str
    scopes: set[str]

def require_context(authorization: str = Header(...)) -> RequestContext:
    if not authorization.startswith('Bearer '):
        raise HTTPException(status_code=401, detail='missing bearer token')
    claims = decode_access_token(authorization[7:])
    if claims is None:
        raise HTTPException(status_code=401, detail='invalid token')
    return RequestContext(
        subject=claims['sub'],
        tenant_id=claims['tenant_id'],
        role=claims.get('role', 'member'),
        scopes=set(claims.get('scopes', )),
    )

def publish_event(ctx: RequestContext, body: dict) -> dict:
    topic = body['topic']
    if not topic.startswith(f'{ctx.tenant_id}.'):
        raise HTTPException(status_code=403, detail='tenant boundary violation')
    broker.publish(topic=topic, payload=body['payload'], headers={'tenant_id': ctx.tenant_id})
    return {'accepted': True}

@router.post('/v1/events')
def publish(body: dict, ctx: RequestContext = Depends(require_context)):
    return publish_event(ctx, body)

@router.post('/admin/tenants/{tenant_id}/replay')
def replay(tenant_id: str, event_id: str, authorization: str = Header(...)) -> dict:
    ctx = require_context(authorization)
    if ctx.role != 'platform_admin':
        raise HTTPException(status_code=403, detail='platform admin required')
    if tenant_id != ctx.tenant_id and ctx.role != 'platform_admin':
        raise HTTPException(status_code=403, detail='tenant mismatch')
    broker.replay(tenant_id=tenant_id, event_id=event_id)
    return {'accepted': True}

